  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}

