/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. A deleted top-level comment takes its
 * thread with it — nothing to anchor the replies to once the opener is gone.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null && comment.archivedAt === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

input.new_string:
/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply descending from it, directly or through
 * other replies, in posting order. A deleted comment stays in place as a
 * placeholder (archived, text blanked) so the replies under it keep their anchor.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  // Rows arrive in posting order and a reply is always posted after its parent,
  // so one pass resolves every comment to its top-level ancestor.
  const rootOf = new Map<string, string>();
  const repliesBy = new Map<string, CommentWithAuthor[]>();
  const topLevel: CommentWithAuthor[] = [];

  for (const row of rows) {
    const comment: CommentWithAuthor = {
      ...toComment(row.comment),
      author: toUser(row.author),
    };

    if (comment.parentId === null) {
      rootOf.set(comment.id, comment.id);
      topLevel.push(comment);
      continue;
    }

    const root = rootOf.get(comment.parentId);
    if (root === undefined) continue;
    rootOf.set(comment.id, root);
    const bucket = repliesBy.get(root) ?? [];
    bucket.push(comment);
    repliesBy.set(root, bucket);
  }

  return topLevel.map((comment) => ({
    comment: asThreadEntry(comment),
    replies: (repliesBy.get(comment.id) ?? []).map(asThreadEntry),
  }));
}

/** Deleted comments keep their identity and position but lose their content. */
function asThreadEntry(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "", mentionedUserIds: [], editedAt: null };
}

